// The map room (UR-T9): the levels a match can be played on. The 2013 original's maproom (design reference only,
// UR-LAW-2) was a world map with a single campaign mission on it, and every round's level was generated by
// randomize_level.gml from the setup screen's polygon count, shapes, rotation and overlap settings. Here the maps are a
// few hand-laid rooms instead: the same 22 x 12 border, so the sixteen seats (Seating), the practice dummies and the laid
// hazards (HazardRules' arcs and gates) stand where they always do, with each map's mirror walls and redirectors kept
// clear of all of them. Every peer builds the same level from the map's index, so only the index goes over the wire.
// U.RICO-T118 (spike, never the default): the original has no map room, so U.RICO-T101 took it out of the flow. The hand-laid
// maps are back in maps.json marked "mapRoomOnly", and maps.json's "mapRoom" flag (false as shipped) puts the map room
// between the players room and the lobby. With it off nothing reaches them: Playable() turns any such pick (an old profile,
// a peer's vote) back into the random arena, so the default flow plays exactly as the original did.
// U.RICO-T111 (spike, never the default): a map-room-only map may set maps.json's "hazards" to lay the arcs, laser gates and
// foliage on its rounds (MapInfo.LaysHazards, read by GameAuthority.ResetHazards); every shipped map says false.
using System;
using System.Collections.Generic;

namespace Rea.Ricochet.Core.Level
{
    using Rea.Ricochet.Core.Aim;
    using Rea.Ricochet.Core.Match;
    /// <summary>One map: a name and a line for the map room, and the level it builds.</summary>
    public sealed class MapInfo
    {
        private readonly Func<Level> _build;

        internal MapInfo(int index, string id, string name, string description, Func<Level> build, bool random = false, bool mapRoomOnly = false,
            bool laysHazards = false)
        {
            IsRandom = random;
            MapRoomOnly = mapRoomOnly;
            LaysHazards = laysHazards;
            Index = index;
            Id = id;
            Name = name;
            Description = description;
            _build = build;
        }

        /// <summary>Its place in <see cref="Maps.All"/>: what the match vote carries.</summary>
        public int Index { get; }

        /// <summary>The map's id in maps.json ("crossfire").</summary>
        public string Id { get; }

        public string Name { get; }

        /// <summary>One line for the map room.</summary>
        public string Description { get; }

        /// <summary>True for the random arena (UR-T23): every round is laid afresh from a seed by <see cref="LevelGenerator"/>.</summary>
        public bool IsRandom { get; }

        /// <summary>
        /// U.RICO-T118: a hand-laid map only the optional map room offers (Crossfire, Pillars, Funnel); never played while the
        /// map room is off (<see cref="Maps.Playable"/>).
        /// </summary>
        public bool MapRoomOnly { get; }

        /// <summary>
        /// U.RICO-T111 (spike, never the default): true when maps.json's "hazards" lays this map's rounds with the electric
        /// arcs, laser gates and foliage (HazardRules) even while hazards.json's layHazards is off. The original laid none
        /// (U.RICO-T91), so only a map-room-only map may ask for them and every shipped map says false: while the map room is
        /// off such a map is never played (<see cref="Maps.Playable"/>), so the default game stays bare.
        /// </summary>
        public bool LaysHazards { get; }

        /// <summary>A fresh copy of the map's level (walls and redirectors, no hazards); a random map's is the one for seed 1.</summary>
        public Level Build() => IsRandom ? LevelGenerator.Generate(1).Level : _build();

        /// <summary>
        /// The arena for one round: a random map's level and seat spots come from <paramref name="seed"/> (randomize_level.gml,
        /// randomize_player_position.gml), laid by the settings the seed carries (<see cref="LevelSeeds"/>); a hand-laid map
        /// is always itself with the fixed seat spots.
        /// </summary>
        public RoundLayout Layout(int seed)
        {
            if (IsRandom)
            {
                return LevelGenerator.Generate(LevelSeeds.Dice(seed), LevelSeeds.Settings(seed));
            }

            var spots = new Vec2[MatchRules.MaxSeats];
            for (int i = 0; i < spots.Length; i++)
            {
                spots[i] = Seating.SpawnPoint(i);
            }

            return new RoundLayout(_build(), spots);
        }
    }

    public static class Maps
    {
        /// <summary>The random arena's index (the default map).</summary>
        public static int RandomIndex => Data.RandomMapIndex;

        /// <summary>Every map, in the order the map room lists them (maps.json).</summary>
        public static IReadOnlyList<MapInfo> All => Data.Maps;

        public static int Count => Data.Maps.Count;

        private static Rea.Ricochet.Core.Data.GameData Data => Rea.Ricochet.Core.Data.GameData.Current;

        /// <summary>A map index the map room can show: anything out of range is the first map.</summary>
        public static int Clamp(int index) => index >= 0 && index < Count ? index : 0;

        /// <summary>The map at <paramref name="index"/> (the first one when it is out of range).</summary>
        public static MapInfo At(int index) => Data.Maps[Clamp(index)];

        /// <summary>The next map, wrapping (the map room's arrows).</summary>
        public static int Next(int index) => (Clamp(index) + 1) % Count;

        /// <summary>The previous map, wrapping.</summary>
        public static int Previous(int index) => (Clamp(index) + Count - 1) % Count;

        /// <summary>
        /// U.RICO-T118: true when maps.json switches the optional map room on (false as shipped: the original's flow, Players'
        /// Start straight on to the game).
        /// </summary>
        public static bool MapRoomEnabled => Data.MapRoomEnabled;

        /// <summary>
        /// U.RICO-T118: the maps the map room lists, in order: the random arena first, then the hand-laid ones. The practice
        /// range stays a test fixture and is not offered.
        /// </summary>
        public static IReadOnlyList<MapInfo> InMapRoom
        {
            get
            {
                var listed = new List<MapInfo> { At(RandomIndex) };
                foreach (MapInfo map in All)
                {
                    if (map.MapRoomOnly)
                    {
                        listed.Add(map);
                    }
                }

                return listed;
            }
        }

        /// <summary>
        /// U.RICO-T118: the map a match may really be played on: <paramref name="index"/> itself, except a map-room-only map while
        /// the map room is off, which is the random arena (every round the random level, as the original played).
        /// </summary>
        public static int Playable(int index) => !MapRoomEnabled && At(index).MapRoomOnly ? RandomIndex : Clamp(index);
    }
}
